using System;
using UnityEngine;

namespace Astrea;

public class DiceToPlayerToBurstVFX : MonoBehaviour
{
	[Header("Dice To Player")]
	[SerializeField]
	private float diceToPlayerDelay;

	[SerializeField]
	private AnimationCurve diceToPlayerMovementCurve;

	[SerializeField]
	private float diceToPlayerMovementDuration;

	[SerializeField]
	private float diceToPlayerHeight;

	[SerializeField]
	private float afterDiceToPlayerDelay;

	[SerializeField]
	private Vector3 playerPositionAdjustment;

	[Header("Dice To Player Particles")]
	[SerializeField]
	protected ParticleSystem diceToPlayerParticleSystem;

	[SerializeField]
	private ParticleEmissionController diceToPlayerParticleEmissionController;

	[Header("Burst VFX")]
	[SerializeField]
	private GameObject burstVFXPrefab;

	public void Initialize(Vector3 position, bool spawnBurst, Action afterDiceToPlayerActionAfterDelay)
	{
		base.transform.position = position;
		diceToPlayerParticleEmissionController.SetActive(value: true);
		InitializeParticle();
		InvokeAlternatives.Invoke(this, diceToPlayerDelay, delegate
		{
			Vector3 targetPosition = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.transform.position + playerPositionAdjustment;
			StartCoroutine(CoroutineUtility.MoveRoutineWithArc(diceToPlayerMovementDuration, diceToPlayerMovementCurve, null, base.transform, base.transform.position, targetPosition, diceToPlayerHeight, delegate
			{
				ParticleArrivedOnPlayer();
				if (spawnBurst)
				{
					SpawnBurst();
				}
				InvokeAlternatives.Invoke(this, afterDiceToPlayerDelay, delegate
				{
					afterDiceToPlayerActionAfterDelay?.Invoke();
					diceToPlayerParticleEmissionController.SetActive(value: false);
					ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject, 2f);
				});
			}));
		});
	}

	private void SpawnBurst()
	{
		if (ReferenceSingleton<PoolHandler>.Instance.GetObject(burstVFXPrefab.name, base.transform.position, 4f) == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(burstVFXPrefab);
			ReferenceSingleton<PoolHandler>.Instance.GetObject(burstVFXPrefab.name, base.transform.position, 4f);
		}
	}

	protected virtual void InitializeParticle()
	{
	}

	protected virtual void ParticleArrivedOnPlayer()
	{
	}
}
